# Find all incomplete 2x2 bboxes in demo 2
def find_incomplete_bboxes(grid):
    """Find all 2x2 bboxes with exactly 3 non-background cells"""
    incomplete = []
    bg = 4  # Demo 2 background
    for r in range(26):
        for c in range(13):
            bbox = [grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]]
            non_bg = [bg]  # Background first
            for cell in bbox:
                if cell != bg:
                    non_bg.append(cell)
            if len(set(non_bg)) == 2 and bg in set(non_bg):  # Has BG and one other color count=3
                if sum(1 for x in bbox if x != bg) == 3:
                    # Exactly 3 non-bg, 1 bg -> incomplete
                    bp = [i for i in range(4) if bbox[i] == bg][0]  # Missing position (0=TL,1=TR,2=BL,3=BR)
